create table base_mat_bom
(
    bom_id          bigint auto_increment comment '主键'
        primary key,
    father_mat_code varchar(64)                     null comment '父物料编码',
    father_mat_num  decimal(24, 6) default 0.000000 null comment '父项数量',
    child_no        int                             null comment '子项行项目号',
    child_mat_code  varchar(64)                     null comment '子项物料编码',
    child_mat_num   decimal(24, 6) default 0.000000 null comment '子项数量',
    is_fictitious   char           default '0'      null comment '是否虚拟键',
    create_by       varchar(64)                     null comment '创建人',
    create_time     datetime                        null comment '创建时间',
    update_by       varchar(64)                     null comment '修改人',
    update_time     datetime                        null comment '更新时间'
)
    comment '物料BOM' collate = utf8mb4_general_ci
                      row_format = DYNAMIC;

